import Foundation

public struct SendMessageRequest: Encodable, Sendable {
    /// Stable end-to-end identifier (`cid_<uuid v4 lowercase>`) generated by the
    /// client BEFORE the request is dispatched. Required by the Phase 4 contract
    /// (spec §6.2 — `services/gateway/src/socketio/handlers/MessageHandler.ts`
    /// `_sendResponse()` echoes it back in the ACK, and the gateway uses it for
    /// the unique-index dedup that prevents duplicate inserts on retry). The
    /// stored property is non-optional so the value is always serialized; the
    /// initializer accepts an optional argument for source compatibility and
    /// auto-generates a fresh `cid_*` when nil.
    public let clientMessageId: String
    public let content: String?
    public let originalLanguage: String?
    public let replyToId: String?
    public let storyReplyToId: String?
    public let forwardedFromId: String?
    public let forwardedFromConversationId: String?
    public let attachmentIds: [String]?
    public var expiresAt: Date?
    public var ephemeralDuration: Int?
    public var isViewOnce: Bool?
    public var maxViewOnceCount: Int?
    public var isBlurred: Bool?
    public var effectFlags: UInt32?
    public var isEncrypted: Bool?
    public var encryptionMode: String?
    /// Lieu partagé attaché au message — clé JSON `location`, celle que le
    /// schéma REST valide déjà (`routes/conversations/messages.ts`, champ
    /// `location` passé à `parseSharedPlace`). L'encodage synthétisé omet les
    /// optionnels nil : un `location` nil n'apparaît PAS dans le corps envoyé.
    public var location: SharedPlace?
    /// Fan-out de partage — clé JSON `copyAttachmentsFromMessageId`. Le serveur
    /// crée de NOUVELLES `MessageAttachment` pointant les MÊMES fichiers
    /// (`filePath`/`fileUrl`) que celles du message source, **sans** écrire
    /// `forwardedFromId` : aucun destinataire ne voit de badge « Transféré
    /// depuis … ». Réutiliser les `attachmentIds` de la source les
    /// DÉPLACERAIT (`associateAttachmentsToMessage` est un `updateMany`,
    /// `AttachmentService.ts:161-173`), ce qui les retirerait au premier
    /// destinataire. Contrat serveur :
    /// `docs/superpowers/plans/2026-08-19-forward-reach.md` Task 5.
    /// L'encodage synthétisé omet les optionnels nil.
    public var copyAttachmentsFromMessageId: String?
    /// Sticker du message (#4823) — clé JSON `sticker`, que le gateway range
    /// sous `metadata.sticker` et ressert hissée. Le PNG rendu voyage à part,
    /// en pièce jointe image ordinaire (`attachmentIds`). L'encodage
    /// synthétisé omet les optionnels nil : un `sticker` nil n'apparaît PAS
    /// dans le corps envoyé.
    public var sticker: MessageSticker?
    /// **La PIÈCE que cette réponse cite** (#6164, moitié ÉCRITURE) — clé JSON
    /// `attachmentReplyTo`, que `messages-send.ts` valide
    /// (`z.object({ attachmentId: z.string().min(1) }).optional()`) puis ADMET
    /// par `admitAttachmentReply` avant de la ranger sous
    /// `metadata.attachmentReplyTo`.
    ///
    /// **Ce champ n'a de sens qu'avec `replyToId`** : citer une pièce sans
    /// citer son message est REFUSÉ côté serveur (« Citer une pièce jointe
    /// exige de citer le message qui la porte »), et la garde relit la ligne
    /// pour vérifier qu'elle appartient bien au message cité.
    ///
    /// **Ce champ N'EST PAS transportable par le socket.** `MessageHandler.ts`
    /// ne le lit nulle part et `admitAttachmentReply` n'y est pas wiré : un
    /// envoi qui le porte doit rester sur le POST REST. La règle vit chez
    /// l'appelant (`ConversationViewModel.sendMessage`), qui seul connaît les
    /// deux transports — mais elle se lit ICI, parce que c'est ici qu'on est
    /// tenté d'ajouter le champ à un autre corps.
    ///
    /// L'encodage synthétisé omet les optionnels nil : une réponse ordinaire
    /// n'a AUCUNE clé `attachmentReplyTo` dans son corps.
    public var attachmentReplyTo: QuotedAttachmentSend?
    /// **Les pièces CHOISIES d'un transfert** (#9914, #10947) — clé JSON
    /// `forwardedAttachmentIds`, toujours avec `forwardedFromId`. Absente, la
    /// passerelle recopie tout le lot (ancien comportement). Chaque id doit être
    /// une pièce du message source, sinon refus `forwarded-attachment-not-in-source`.
    public var forwardedAttachmentIds: [String]?
    /// **L'envoi libsignal (#3707, spec § 4.3)** — `encryptionProtocol`
    /// (`libsignal-v1`), `encryptedContent` (le marqueur non vide), les
    /// `envelopes` (une par appareil destinataire), `encryptionMetadata`
    /// (l'appareil émetteur) et les appareils de l'émetteur qu'il n'a pas
    /// approuvés. Le texte ne voyage QUE dans les enveloppes : `content` reste
    /// absent. Un envoi en clair n'a aucune de ces clés.
    public var encryptionProtocol: String?
    public var encryptedContent: String?
    public var encryptionMetadata: E2EEWireMetadata?
    public var envelopes: [E2EEOutgoingEnvelope]?
    public var unapprovedOwnDevices: [UInt32]?

    public init(content: String?, originalLanguage: String? = nil, replyToId: String? = nil, storyReplyToId: String? = nil, forwardedFromId: String? = nil, forwardedFromConversationId: String? = nil, attachmentIds: [String]? = nil, expiresAt: Date? = nil, ephemeralDuration: Int? = nil, isViewOnce: Bool? = nil, maxViewOnceCount: Int? = nil, isBlurred: Bool? = nil, effectFlags: UInt32? = nil, isEncrypted: Bool? = nil, encryptionMode: String? = nil, clientMessageId: String? = nil, location: SharedPlace? = nil, copyAttachmentsFromMessageId: String? = nil, sticker: MessageSticker? = nil, attachmentReplyTo: QuotedAttachmentSend? = nil, forwardedAttachmentIds: [String]? = nil) {
        self.clientMessageId = clientMessageId ?? ClientMessageId.generate()
        self.content = content; self.originalLanguage = originalLanguage
        self.replyToId = replyToId; self.storyReplyToId = storyReplyToId; self.forwardedFromId = forwardedFromId
        self.forwardedFromConversationId = forwardedFromConversationId; self.attachmentIds = attachmentIds
        self.expiresAt = expiresAt; self.ephemeralDuration = ephemeralDuration
        self.isViewOnce = isViewOnce; self.maxViewOnceCount = maxViewOnceCount
        self.isBlurred = isBlurred; self.effectFlags = effectFlags
        self.isEncrypted = isEncrypted; self.encryptionMode = encryptionMode
        self.location = location
        self.copyAttachmentsFromMessageId = copyAttachmentsFromMessageId
        self.sticker = sticker
        self.attachmentReplyTo = attachmentReplyTo
        self.forwardedAttachmentIds = forwardedAttachmentIds
    }
}

public extension SendMessageRequest {
    /// Le corps d'un envoi libsignal (#3707, spec § 4.3) : aucun `content`,
    /// aucune langue — le texte ne voyage que dans les enveloppes.
    static func libsignal(
        clientMessageId: String,
        replyToId: String? = nil,
        storyReplyToId: String? = nil,
        senderDeviceId: UInt32,
        envelopes: [E2EEOutgoingEnvelope],
        unapprovedOwnDevices: [UInt32],
        regimeEpoch: Int? = nil
    ) -> SendMessageRequest {
        var request = SendMessageRequest(
            content: nil, replyToId: replyToId, storyReplyToId: storyReplyToId,
            isEncrypted: true, encryptionMode: E2EEWire.mode, clientMessageId: clientMessageId
        )
        request.encryptionProtocol = E2EEWire.libsignalProtocol
        request.encryptedContent = E2EEWire.encryptedContentMarker
        request.encryptionMetadata = E2EEWireMetadata(senderDeviceId: senderDeviceId, regimeEpoch: regimeEpoch)
        request.envelopes = envelopes
        request.unapprovedOwnDevices = unapprovedOwnDevices.isEmpty ? nil : unapprovedOwnDevices
        return request
    }
}
